import { h } from 'preact';
import PropTypes from 'prop-types';
import { WCAGColorContrast } from '@utilities/color/WCAGColorContrast';

// WCAG AA minimum contrast ratio for normal text
const MIN_CONTRAST_RATIO = 4.5;

/**
 * Warns when the given text and background colors don't meet WCAG AA contrast.
 * @param {string} props.textColor Six-digit hex color, e.g. "#1a2b3c"
 * @param {string} props.backgroundColor Six-digit hex color, e.g. "#ffffff"
 */
export const ColorContrastWarning = ({ textColor, backgroundColor }) => {
  const ratio = WCAGColorContrast.ratio(
    textColor.replace('#', ''),
    backgroundColor.replace('#', ''),
  );

  if (ratio >= MIN_CONTRAST_RATIO) return null;

  return <p role="alert">These colors are hard to read together</p>;
};

